static void ck(cudaError_t e){if(e!=cudaSuccess)throw std::runtime_error(cudaGetErrorString(e));}
template<class T>struct A{unsigned char*raw;T*d;int n;A(int count):n(count){ck(cudaMalloc(&raw,n*sizeof(T)+512));d=(T*)(raw+256);ck(cudaMemset(raw,0xa5,n*sizeof(T)+512));ck(cudaMemset(d,0,n*sizeof(T)));}std::vector<unsigned char>capture(){std::vector<unsigned char>v(n*sizeof(T)+512);ck(cudaMemcpy(v.data(),raw,v.size(),cudaMemcpyDeviceToHost));for(int j=0;j<256;j++)need(v[j]==0xa5&&v[v.size()-256+j]==0xa5,"actual guard byte");return v;}std::vector<T>host(){std::vector<T>h(n);ck(cudaMemcpy(h.data(),d,n*sizeof(T),cudaMemcpyDeviceToHost));return h;}~A(){cudaFree(raw);}};
static void init(std::vector<Particle>&p,const std::vector<double>&x,const std::vector<double>&v){memset(p.data(),0,p.size()*sizeof(Particle));for(size_t i=0;i<p.size();i++){p[i].x=x[i];p[i].v=v[i];p[i].alive=true;}}
int main(){try{auto cs=cases();auto rawdir=std::filesystem::path(__FILE__).parent_path()/"../../.porting-state/portable_julia/sheath_primary/cuda";std::filesystem::create_directories(rawdir);std::string capture=std::to_string(std::chrono::system_clock::now().time_since_epoch().count());const double phiscale=K*(ELECTRON_TEMP*EV_TO_K)/QE,escale=phiscale/DX,rhoscale=QE*PLASMA_DEN;
for(int trial=0;trial<=5;trial++){double seconds=0;std::vector<double>prefix,out;std::ofstream raw;std::string rawpath=(rawdir/(capture+"_trial"+std::to_string(trial)+".physical.bin")).string();if(trial){raw.open(rawpath,std::ios::binary);need(raw.good(),"raw file");printf("SHEATH_RAW trial=%d path=%s\n",trial,rawpath.c_str());}
for(size_t ci=0;ci<cs.size();ci++){const auto&c=cs[ci];std::vector<double>phi(101,0),rho(101),ef(101);std::vector<float>ni(101),ne(101);domain.phi=phi.data();domain.rho=rho.data();domain.ef=ef.data();domain.ndi=ni.data();domain.nde=ne.data();std::vector<Particle>hi(c.n),he(c.n);init(hi,c.ions_x,c.ions_v);init(he,c.electrons_x,c.electrons_v);Species ions{},electrons{};ions.mass=16*AMU;ions.charge=QE;ions.spwt=PLASMA_DEN*domain.xl/c.n;ions.np=ions.np_alloc=c.n;ions.part=hi.data();electrons.mass=ME;electrons.charge=-QE;electrons.spwt=ions.spwt;electrons.np=electrons.np_alloc=c.n;electrons.part=he.data();A<float>di(101),de(101);A<double>df(101);A<Particle>pi(c.n),pe(c.n);ck(cudaMemcpy(pi.d,hi.data(),c.n*sizeof(Particle),cudaMemcpyHostToDevice));ck(cudaMemcpy(pe.d,he.data(),c.n*sizeof(Particle),cudaMemcpyHostToDevice));ck(cudaDeviceSynchronize());auto init_i=pi.host(),init_e=pe.host();prefix.push_back(ci);prefix.push_back(c.n);prefix.push_back(c.steps);for(auto&parts:{init_i,init_e})for(auto p:parts){prefix.push_back(p.x);prefix.push_back(p.v);prefix.push_back(p.alive?1.:0.);}for(auto&parts:{init_i,init_e})for(auto p:parts)need(p.alive,"initialized alive");for(int j=0;j<c.n;j++)need(init_i[j].x==c.ions_x[j]&&init_i[j].v==c.ions_v[j]&&init_e[j].x==c.electrons_x[j]&&init_e[j].v==c.electrons_v[j],"actual initialized particle input");
auto snapshot=[&](int stage,int step){if(!trial)return;int32_t header[]={int32_t(ci),stage,step,5};raw.write((char*)header,sizeof(header));auto save=[&](auto&a){auto v=a.capture();uint64_t len=v.size();raw.write((char*)&len,8);raw.write((char*)v.data(),v.size());};save(pi);save(pe);save(di);save(de);save(df);need(raw.good(),"physical write");};
auto timed=[&](auto fn){auto start=std::chrono::steady_clock::now();fn();seconds+=std::chrono::duration<double>(std::chrono::steady_clock::now()-start).count();};
double sp_time=0;auto scattercheck=[&](){auto ri=di.host(),re=de.host();need(witness_deposition(hi.data(),c.n,ri.data(),ni.data(),ions.spwt)==0,"independent ion deposition");need(witness_deposition(he.data(),c.n,re.data(),ne.data(),electrons.spwt)==0,"independent electron deposition");};auto fields=[&](bool active){int converged;auto body=[&](){ComputeRho(&ions,&electrons);converged=SolvePotential(phi.data(),rho.data());ComputeEF(phi.data(),ef.data(),df.d);};if(active)timed(body);else body();need(witness_field(ni.data(),ne.data(),rho.data(),phi.data(),ef.data(),converged)==0,"independent Poisson/field");auto actual=df.host();need(actual==ef,"actual GPU field input");if(trial){int32_t h[]={int32_t(ci),1,active?1:0,-1};raw.write((char*)h,sizeof(h));raw.write((char*)ni.data(),101*4);raw.write((char*)ne.data(),101*4);raw.write((char*)rho.data(),101*8);raw.write((char*)phi.data(),101*8);raw.write((char*)ef.data(),101*8);need(raw.good(),"raw CPU physical field trace");}for(int j=0;j<101;j++){out.push_back(ni[j]/(double)PLASMA_DEN);out.push_back(ne[j]/(double)PLASMA_DEN);out.push_back(rho[j]/rhoscale);out.push_back(phi[j]/phiscale);out.push_back(ef[j]/escale);out.push_back(converged?1.:0.);}};
snapshot(0,0);ScatterSpecies(&ions,pi.d,ni.data(),di.d,sp_time);ScatterSpecies(&electrons,pe.d,ne.data(),de.d,sp_time);scattercheck();fields(false);RewindSpecies(&ions,pi.d,df.d);RewindSpecies(&electrons,pe.d,df.d);ck(cudaDeviceSynchronize());auto afteri=pi.host(),aftere=pe.host();need(witness_motion(hi.data(),afteri.data(),c.n,ef.data(),ions.charge/ions.mass,1)==0,"independent ion rewind");need(witness_motion(he.data(),aftere.data(),c.n,ef.data(),electrons.charge/electrons.mass,1)==0,"independent electron rewind");hi=std::move(afteri);he=std::move(aftere);ions.part=hi.data();electrons.part=he.data();snapshot(2,0);
std::string gridpath=(rawdir/(capture+"_trial"+std::to_string(trial)+"_case"+std::to_string(ci)+".dat")).string();file_res=fopen(gridpath.c_str(),"w");need(file_res,"gridfile");fprintf(file_res,"VARIABLES = x nde ndi rho phi ef\n");WriteResults(0);
for(int ts=1;ts<=c.steps;ts++){timed([&](){ScatterSpecies(&ions,pi.d,ni.data(),di.d,sp_time);ScatterSpecies(&electrons,pe.d,ne.data(),de.d,sp_time);});scattercheck();fields(true);timed([&](){PushSpecies(&electrons,pe.d,df.d);PushSpecies(&ions,pi.d,df.d);ck(cudaDeviceSynchronize());});afteri=pi.host();aftere=pe.host();need(witness_motion(hi.data(),afteri.data(),c.n,ef.data(),ions.charge/ions.mass,0)==0,"independent ion push");need(witness_motion(he.data(),aftere.data(),c.n,ef.data(),electrons.charge/electrons.mass,0)==0,"independent electron push");hi=std::move(afteri);he=std::move(aftere);ions.part=hi.data();electrons.part=he.data();snapshot(3,ts);timed([&](){if(ts%25==0){double max_phi=abs(phi[0]);for(int i=0;i<101;i++)if(abs(phi[i])>max_phi)max_phi=abs(phi[i]);printf("TS:%i\tnp_i:%d\tnp_e:%d\tdphi:%.3g\n",ts,ions.np,electrons.np,max_phi-phi[0]);}if(ts%1000==0)WriteResults(ts);});}
fclose(file_res);double vthi=sqrt(2*K*ION_TEMP*EV_TO_K/ions.mass),vthe=sqrt(2*K*ELECTRON_TEMP*EV_TO_K/electrons.mass);for(int s=0;s<2;s++)for(auto p:s?he:hi){out.push_back(p.x/domain.xl);out.push_back(p.v/(s?vthe:vthi));out.push_back(p.alive?1.:0.);}auto guardout=[&](auto&a){auto bytes=a.capture();for(size_t off:{size_t(0),bytes.size()-256})for(int j=0;j<256;j++)out.push_back(bytes[off+j]);};guardout(pi);guardout(pe);guardout(di);guardout(de);guardout(df);if(trial)printf("SHEATH_CASE trial=%d case=%zu n=%d steps=%d cold=%d scatter_kernel_seconds=%.17g alive_i=%zu alive_e=%zu\n",trial,ci,c.n,c.steps,c.cold,sp_time*1e-9,std::count_if(hi.begin(),hi.end(),[](auto p){return p.alive;}),std::count_if(he.begin(),he.end(),[](auto p){return p.alive;}));}
if(trial){raw.close();prefix.insert(prefix.end(),out.begin(),out.end());std::string path="trial"+std::to_string(trial)+".bin";std::ofstream f(path,std::ios::binary);f.write((char*)prefix.data(),prefix.size()*8);f.close();need(f.good(),"primary file");witness_report();printf("STUDY_TRIAL {\"trial\":%d,\"time_seconds\":%.17g,\"correct\":true,\"checked_values\":%zu,\"max_abs_error\":null,\"max_rel_error\":null,\"jit_excluded\":true,\"timing_region\":\"sum3_fullPICmainloops_observerpaused_contextsplit\",\"internal_repeats\":1,\"output_artifact\":{\"path\":\"%s\",\"dtype\":\"float64\",\"count\":%zu,\"byte_order\":\"little\"}}\n",trial,seconds,prefix.size(),path.c_str(),prefix.size());fflush(stdout);}}}catch(const std::exception&e){fprintf(stderr,"%s\n",e.what());return 2;}}
